
SELECT F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0.C_NAME AS C_NAME, F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.O_TOTALPRICE AS O_TOTALPRICE
FROM (
SELECT F0_0.C_NAME AS C_NAME, F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.O_TOTALPRICE AS O_TOTALPRICE, F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", DENSE_RANK() OVER ( ORDER BY F0_0.O_TOTALPRICE DESC NULLS LAST, F0_0.O_ORDERDATE ASC NULLS LAST, F0_0._RESULT_TID) AS _RESULT_TID
FROM (
SELECT F0_0.C_NAME AS C_NAME, F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.O_TOTALPRICE AS O_TOTALPRICE, F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", DENSE_RANK() OVER ( ORDER BY F0_0.C_NAME, F0_0.C_CUSTKEY, F0_0.O_ORDERKEY, F0_0.O_ORDERDATE, F0_0.O_TOTALPRICE) AS _RESULT_TID
FROM (
SELECT F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.C_NAME AS C_NAME, F0_0.L_ORDERKEY AS L_ORDERKEY, F0_0.L_QUANTITY AS L_QUANTITY, F1_0.O_ORDERKEY AS O_ORDERKEY, F1_0.O_CUSTKEY AS O_CUSTKEY, F1_0.O_TOTALPRICE AS O_TOTALPRICE, F1_0.O_ORDERDATE AS O_ORDERDATE, F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F1_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F1_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", GREATEST(F0_0._SETPROV_DUP_COUNT, F1_0._SETPROV_DUP_COUNT) AS _SETPROV_DUP_COUNT
FROM ((
SELECT F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.C_NAME AS C_NAME, F1_0.L_ORDERKEY AS L_ORDERKEY, F1_0.L_QUANTITY AS L_QUANTITY, F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F1_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, GREATEST(F0_0._SETPROV_DUP_COUNT, F1_0._SETPROV_DUP_COUNT) AS _SETPROV_DUP_COUNT
FROM ((
SELECT F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.C_NAME AS C_NAME, F0_0.C_CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, 1 AS _SETPROV_DUP_COUNT
FROM CUSTOMER F0_0) F0_0 CROSS JOIN (
SELECT F0_0.L_ORDERKEY AS L_ORDERKEY, F0_0.L_QUANTITY AS L_QUANTITY, F0_0.L_ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, 1 AS _SETPROV_DUP_COUNT
FROM LINEITEM F0_0) F1_0)) F0_0 CROSS JOIN (
SELECT F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_CUSTKEY AS O_CUSTKEY, F0_0.O_TOTALPRICE AS O_TOTALPRICE, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F1_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", GREATEST(F0_0._SETPROV_DUP_COUNT, F1_0._SETPROV_DUP_COUNT) AS _SETPROV_DUP_COUNT
FROM ((
SELECT F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_CUSTKEY AS O_CUSTKEY, F0_0.O_TOTALPRICE AS O_TOTALPRICE, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.O_ORDERKEY AS PROV_ORDERS_O__ORDERKEY, 1 AS _SETPROV_DUP_COUNT
FROM ORDERS F0_0) F0_0 JOIN (
SELECT F0_0."GROUP_0" AS INNER_L_ORDERKEY, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT
FROM (
SELECT F0_0."AGGR_0" AS "AGGR_0", F0_0.L_ORDERKEY AS "GROUP_0", F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", ROW_NUMBER() OVER (PARTITION BY F0_0.L_ORDERKEY ORDER BY F0_0.L_ORDERKEY) AS _SETPROV_DUP_COUNT
FROM (
SELECT F0_0.L_ORDERKEY AS L_ORDERKEY, F0_0.L_QUANTITY AS L_QUANTITY, F0_0.L_ORDERKEY AS "PROV_LINEITEM_1_L__ORDERKEY", SUM(F0_0.L_QUANTITY) OVER (PARTITION BY F0_0.L_ORDERKEY) AS "AGGR_0"
FROM LINEITEM F0_0) F0_0) F0_0
WHERE (F0_0."AGGR_0" > 300)) F1_0 ON ((F1_0.INNER_L_ORDERKEY = F0_0.O_ORDERKEY)))) F1_0)) F0_0
WHERE ((F0_0.C_CUSTKEY = F0_0.O_CUSTKEY) AND (F0_0.O_ORDERKEY = F0_0.L_ORDERKEY))
ORDER BY O_TOTALPRICE DESC NULLS LAST, O_ORDERDATE ASC NULLS LAST) F0_0) F0_0
WHERE (F0_0._RESULT_TID <= 100);


